import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// Base path for GitHub Pages project sites (e.g. "/Portfolio"). Empty locally.
export const basePath = process.env.NEXT_PUBLIC_BASE_PATH || "";

// Prefix a public asset / route path with the base path. next/image and some
// metadata routes don't apply basePath automatically under `output: export`.
export function asset(path: string) {
  return `${basePath}${path}`;
}
